function sample(f: (x: number) => number, xMin: number, xMax: number, n = 100): Array<[number, number]> {
  const pts: Array<[number, number]> = [];
  for (let i = 0; i < n; i++) {
    const x = xMin + (i / (n - 1)) * (xMax - xMin);
    const y = f(x);
    if (Number.isFinite(y)) pts.push([x, y]);
  }
  return pts;
}

